        this.lab.string = "1. VIP \u09B8\u09C1\u09AA\u09BE\u09B0 \u0997\u09BF\u09AB\u099F \u09AA\u09CD\u09AF\u09BE\u0995\u09C7\u09B0 \u09AA\u09CD\u09B0\u09A4\u09BF\u099F\u09BF \u09B8\u09CD\u09A4\u09B0 \u09B6\u09C1\u09A7\u09C1\u09AE\u09BE\u09A4\u09CD\u09B0 \u098F\u0995\u09AC\u09BE\u09B0 \u0995\u09C7\u09A8\u09BE \u09AF\u09BE\u09AC\u09C7, \n\u09AC\u09B0\u09CD\u09A4\u09AE\u09BE\u09A8 \u09B8\u09CD\u09A4\u09B0 \u09A6\u09CD\u09B0\u09C1\u09A4 \u0986\u09AA\u0997\u09CD\u09B0\u09C7\u09A1 \u0995\u09B0\u09BE\u09B0 \u099C\u09A8\u09CD\u09AF \u09AC\u09CD\u09AF\u09AC\u09B9\u09BE\u09B0 \u0995\u09B0\u09BE \u09B9\u09AF\u09BC\u0964\n2. \u09AD\u09BF\u0986\u0987\u09AA\u09BF \u09A6\u09CD\u09B0\u09C1\u09A4 \u09B0\u09BF\u099A\u09BE\u09B0\u09CD\u099C \u0997\u09BF\u09AB\u099F \u09AA\u09CD\u09AF\u09BE\u0995\u09C7\u099C \u09B8\u09B0\u09BE\u09B8\u09B0\u09BF \u09AC\u09B0\u09CD\u09A4\u09AE\u09BE\u09A8 \n\u09B2\u09C7\u09AD\u09C7\u09B2 \u098F\u09A1\u09BC\u09BF\u09AF\u09BC\u09C7 \u09AA\u09B0\u09AC\u09B0\u09CD\u09A4\u09C0 \u09B8\u09CD\u09A4\u09B0\u09C7 \u09AA\u09CD\u09B0\u09AC\u09C7\u09B6 \u0995\u09B0\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7\u0964\n\u09E9. \u098F\u0987 \u0995\u09BE\u09B0\u09CD\u09AF\u0995\u09B2\u09BE\u09AA\u09C7\u09B0 \u09AE\u09BE\u09A7\u09CD\u09AF\u09AE\u09C7 \u09B0\u09BF\u099A\u09BE\u09B0\u09CD\u099C \u0995\u09B0\u09BE \u0996\u09C7\u09B2\u09CB\u09AF\u09BC\u09BE\u09A1\u09BC\u09C7\u09B0\u09BE \u098F\u0995\u0987 \nVIP \u09B8\u09C1\u09AC\u09BF\u09A7\u09BE \u0989\u09AA\u09AD\u09CB\u0997 \u0995\u09B0\u09A4\u09C7 \u09AA\u09BE\u09B0\u09AC\u09C7\u09A8\u0964";
